ius:8px;background:#e8e5db;margin:12px 0 7px;overflow:hidden}.progress-fill{height:100%;background:linear-gradient(90deg,#c59a59,#e3c88e);border-radius:8px;transition:width .3s}.renown-note{font-size:10px;color:#99958d}.side-visitor{display:flex;align-items:center;gap:10px;margin:0 9px;padding:12px 4px;border-top:1px solid var(--line)}.visitor-portrait{height:34px;width:34px;border-radius:50%;background:#edf1e8;display:grid;place-items:center;font-size:17px}.visitor-name{font-size:10px;color:#a39d92;margin-bottom:3px}.visitor-desc{font-size:11px;font-weight:600}.online-dot{margin-left:auto;width:7px;height:7px;border-radius:50%;background:#8aa68a}.sidebar-footer{margin-top:auto;border-top:1px solid var(--line);padding:17px 10px 0;display:flex;align-items:center;gap:10px}.weather-icon{width:32px;height:32px;border-radius:10px;background:#fbf2da;color:#d7a550;display:grid;place-items:center;font-size:17px}.sidebar-footer strong,.sidebar-footer span{display:block}.sidebar-footer strong{font-size:11px}.sidebar-footer span{font-size:10px;color:#98988e;margin-top:3px}.main-area{flex:1;min-width:0}.topbar{height:72px;background:#fffefa;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 40px}.breadcrumbs{display:flex;align-items:center;gap:10px;font-size:11px;color:#a29d91;letter-spacing:.7px}.breadcrumbs i{font-style:normal;color:#c6c0b4;font-size:18px}.breadcrumbs strong{font-size:12px;letter-spacing:0;color:#526174}.topbar-right{display:flex;align-items:center;gap:20px}.date-pill{border-radius:20px;padding:8px 12px;background:#f7f5ed;color:#777b7a;font-size:11px}.date-pill span{color:#d5a45c;margin-right:6px}.date-pill b{color:#37465b;margin-left:3px}.wallet{display:flex;align-items:center;gap:6px;font-size:13px}.wallet b{font-size:13px}.wallet small{color:#99988f}.coin{color:#c89e59}.avatar-button{width:39px;height:39px;padding:0;border:2px solid #e8dfce;background:#edf0f3;border-radius:50%;overflow:hidden}.avatar-button img{width:100%;height:100%;object-fit:cover;object-position:50% 31%;transform:scale(1.35)}.mobile-menu{display:none;border:0;background:none;font-size:20px}.view-container{max-width:1450px;margin:auto;padding:30px 40px 48px}.eyebrow{font-size:10px;letter-spacing:1.7px;font-weight:700;color:#b2925d;text-transform:uppercase}.page-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:23px}.page-heading h1{font:600 29px 'Playfair Display',serif;margin:7px 0 6px;letter-spacing:-.3px}.page-heading p{margin:0;color:#8a8e91;font-size:12px}.primary-btn,.secondary-btn,.quiet-btn{border:0;border-radius:8px;padding:10px 15px;font-weight:600;font-size:11px;transition:transform .15s,background .15s}.primary-btn{background:var(--navy);color:#fff;box-shadow:0 4px 10px #2636501c}.primary-btn:hover{background:#394e6d;transform:translateY(-1px)}.secondary-btn{background:#f2eee4;color:#69747c}.secondary-btn:hover,.quiet-btn:hover{background:#eae5d8}.quiet-btn{background:transparent;color:#7a8490}.home-grid{display:grid;grid-template-columns:minmax(0,1.58fr) minmax(270px,.88fr);gap:20px}.hero-card{height:305px;border-radius:13px;overflow:hidden;position:relative;background:#35475e;box-shadow:var(--shadow)}.hero-scene{position:absolute;inset:0;background:linear-gradient(90deg,#1d2b42e8 0%,#26364dcc 42%,#26364d12 100%),linear-gradient(0deg,#17263b66,transparent 58%),radial-gradient(ellipse at 75% 15%,#f4dda04c 0 9%,transparent 10%),linear-gradient(135deg,#84948b 0%,#526876 42%,#b5a888 100%)}.hero-scene:before{content:'';position:absolute;inset:0 0 0 43%;opacity:.65;background:linear-gradient(90deg,transparent 0 10%,#e0c999 10.5% 11.5%,transparent 12% 27%,#e0c999 27.5% 28.5%,transparent 29% 44%,#e0c999 44.5% 45.5%,transparent 46%),linear-gradient(0deg,#6a4c38 0 7%,transparent 7.3% 82%,#e7d8b8 82.4% 84%,transparent 84.4%),linear-gradient(90deg,#ded0b0 0 5%,transparent 5.5% 95%,#ded0b0 95.5% 100%)}.hero-scene:after{content:'✦';position:absolute;right:1