inmax(0,1.35fr) minmax(270px,.8fr);gap:20px}.panel{background:var(--cream);border:1px solid var(--line);border-radius:11px;padding:17px 18px}.panel-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.panel-head h3{margin:0;font:600 16px 'Playfair Display',serif}.panel-head .link-btn{border:0;background:transparent;color:#aa8b59;font-size:10px;font-weight:700}.artifact-list{display:grid;gap:9px}.artifact-row{display:flex;align-items:center;gap:11px;padding:8px;border:1px solid #efede6;border-radius:8px;background:white}.artifact-art{width:42px;height:42px;display:grid;place-items:center;border-radius:7px;font-size:21px;background:#f5eee0}.artifact-copy{flex:1;min-width:0}.artifact-copy strong{display:block;font-size:11px}.artifact-copy span{display:block;color:#999b97;font-size:9px;margin-top:4px}.rarity{border-radius:20px;background:#eef3ec;padding:4px 7px;color:#7b9978;font-size:9px;font-weight:700}.empty-note{color:#989b98;font-size:11px;padding:14px 4px;line-height:1.6}.activity-list{display:grid;gap:14px}.activity-item{display:flex;gap:10px;align-items:flex-start}.activity-dot{width:27px;height:27px;border-radius:50%;display:grid;place-items:center;background:#f7f1e4;font-size:13px;flex-shrink:0}.activity-item strong{display:block;font-size:10px}.activity-item span{display:block;color:#969996;font-size:9px;margin-top:3px}.quick-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px}.quick-action{border:1px solid var(--line);background:#fff;border-radius:8px;text-align:left;padding:10px;color:#687584;font-size:10px;font-weight:600}.quick-action span{font-size:15px;margin-right:7px;color:#b38d55}.section-gap{margin-top:20px}.card-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.item-card{background:var(--cream);border:1px solid var(--line);border-radius:11px;overflow:hidden;position:relative;display:flex;flex-direction:column}.item-art{height:112px;display:grid;place-items:center;font-size:39px;positi