 12px;border-radius:7px;font:600 13px 'Playfair Display',serif;z-index:1}.room-displays{position:absolute;inset:0;display:flex;align-items:flex-end;justify-content:center;gap:30px;padding-bottom:28px}.display-pedestal{height:62px;width:74px;border-radius:9px 9px 3px 3px;background:linear-gradient(90deg,#9a7958,#c5a77e,#9a7958);position:relative;display:grid;place-items:center;font-size:28px;box-shadow:0 8px 8px #58604e33}.display-pedestal:before{content:'';position:absolute;top:-7px;left:-5px;right:-5px;height:9px;border-radius:4px;background:#ddc69b}.display-pedestal span{transform:translateY(-21px);filter:drop-shadow(0 3px 2px #64644b55)}.collection-stats{display:flex;gap:10px;margin:0 0 17px}.mini-stat{border:1px solid var(--line);background:#fffefa;border-radius:8px;padding:9px 13px;font-size:10px;color:#92958f}.mini-stat b{color:#41516a;margin-right:4px}.guild-layout{display:grid;grid-template-columns:1.05fr .95fr;gap:18px}.commission-card{padding:15px;border:1px solid var(--line);border-radius:10px;background:#fff;margin-bottom:10px}.commission-top{display:flex;align-items:center;gap:11px}.adventurer-avatar{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:#eaf0e8;font-size:22px}.commission-copy{flex:1}.commission-copy strong{font:600 14px 'Playfair Display',serif}.commission-copy span{display:block;color:#999b96;font-size:9px;margin-top:4px}.commission-card p{color:#818984;font-size:10px;line-height:1.6;margin:11px 0}.commission-foot{display:flex;align-items:center;justify-content:space-between}.commission-reward{font-size:9px;color:#a5824e}.commission-progress{margin-top:11px;height:4px;border-radius:5px;background:#ece9e1;overflow:hidden}.commission-progress span{display:block;height:100%;background:#95aa8f;border-radius:5px}.estate-layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(250px,.8fr);gap:19px}.estate-room{height:330px;background:linear-gradient(180deg,#e6e9df 0 75%,#b99f7d 75% 100%);border-radius:12