  {id:'bench',name:'Gallery Window Bench',icon:'🪑',price:88,desc:'A comfortable pause between exhibits.',room:'gallery'},
  {id:'flowers',name:'Brass Flower Stand',icon:'💐',price:52,desc:'Fresh blooms welcome every visitor.',room:'gallery'}
];
const adventurers = [
  {id:'lina',name:'Lina Farrow',role:'Elven ranger',icon:'🏹',cost:58,days:2,loot:'Azure Griffin Feather',quote:'I know a trail where the clouds leave souvenirs.'},
  {id:'bram',name:'Bramble Underbough',role:'Halfling delver',icon:'🧙',cost:72,days:2,loot:'Clockwork Garden Key',quote:'Old tunnels, old locks. My favorite sort of afternoon.'},
  {id:'sable',name:'Sable Venn',role:'Human relic-hunter',icon:'🗡️',cost:86,days:3,loot:'Masquerade of Moths',quote:'There is a moonlit ruin with my name on it.'}
];
const guests = [
  {name:'Mira, a traveling herbalist',icon:'🌿',line:'“The moonflower display reminds me of home. I could stay here all afternoon.”'},
  {name:'Tomas, a clockwork tinkerer',icon:'⚙️',line:'“That little key is a marvel! I would love to sketch its pattern.”'},
  {name:'Lady Nessa of the Vale',icon:'🦢',line:'“Such a thoughtful collection. You have a talent for finding the wonder in small things.”'},
  {name:'Pip, an apprentice mage',icon:'🔮',line:'“I felt the compass humming before I even came inside!”'},
  {name:'Orin, a wandering bard',icon:'🎻',line:'“Every object has a song. Yours are a very lovely chorus.”'}
];
const initial = {gold:260,day:1,renown:22,owned:['compass','flower','dragoncup'],exhibited:['compass','flower'],furniture:[],missions:[],activities:[],view:'home',guest:0};
let state;
try { state = Object.assign({}, initial, JSON.parse(localStorage.getItem('larkspur-save')||'{}')); } catch { state={...initial}; }
state.owned ||= [...initial.owned]; state.exhibited ||= [...initial.exhibited]; state.furniture ||= []; state.missions ||= []; state.activities ||= [];
let activeView = ['home','gallery','collection','guild','estate'].includes(state.view)?state.view:'home';
const el=(s,root=document)=>root.querySelector(s);
function save(){state.view=activeView;localStorage.setItem('larkspur-save',JSON.stringify(state));updateChrome();}
function updateChrome(){el('#gold-count').textContent=state.gold;el('#day-number').textContent=state.day;el('#footer-day').textContent=state.day;el('#gallery-count').textContent=state.exhibited.length;const level=Math.floor(state.renown/100)+1;el('#renown-level').textContent='Lv. '+level;el('#renown-fill').style.width=(state.renown%100)+'%';el('#renown-note').textContent=level>1?'The town knows your name':'A promising beginning';const g=guests[state.guest%guests.length];el('#guest-name').textContent=g.name;}
function owned(id){return state.owned.includes(id)}
function item(id){return artifacts.find(a=>a.id===id)}
function furnitureItem(id){return furniture.find(a=>a.id===id)}
function getDisplayed(){return state.exhibited.map(item).filter(Boolean)}
function toast(message,error=false){const box=document.createElement('div');box.className='toast'+(error?' error':'');box.innerHTML=message;el('#toast-region').append(box);setTimeout(()=>box.remove(),3100)}
function activity(icon,title,detail){state.activities.unshift({icon,title,detail});state.activities=state.activities.slice(0,5)}
function visit(view){activeView=view;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));el('#crumb-title').textContent={home:'Overview',gallery:'My Gallery',collection:'Collection',guild:'Guild & Market',estate:'My Mansion'}[view];render();save();el('#sidebar').classList.remove('open')}
function heading(eyebrow,title,description,button=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${button}</div>`}
function artifactRow(a){return `<div class="artifact-row"><div class="artifact-art">${a.icon}</div><div class="artifact-copy"><strong>${a.name}</strong><span>${a.kind} · ${a.rarity}</span></div><span class="rarity">${a.rarity}</span></div>`}
function stat(icon,cls,label,value,extra=''){return `<div class="stat-card"><div class="stat-icon ${cls}">${icon}</div><div><small>${label}</small><strong>${value}</strong>${extra?`<span class="stat-extra">${extra}</span>`:''}</div></div>`}
function homeView(){const d=getDisplayed();const activityHtml=state.activities.length?state.activities.slice(0,4).map(a=>`<div class="activity-item"><div class="activity-dot">${a.icon}</div><div><strong>${a.title}</strong><span>${a.detail}</span></div></div>`).join(''):'<div class="empty-note">Your story is just beginning. A new exhibit or expedition will appear here.</div>';const latest=d.length?d.slice(-3).reverse().map(artifactRow).join(''):'<div class="empty-note">Your first discoveries are waiting to be displayed.</div>';return `${heading('A GOOD MORNING, LORD AURELIUS','A little wonder, every day.','Your gallery is ready for its next story.',`<button class="primary-btn" data-action="advance">☀ &nbsp;End the day</button>`)}<div class="home-grid"><section class="hero-card"><div class="hero-scene"></div><div class="hero-copy"><div class="eyebrow">THE LARKSPUR GALLERY</div><h2>Every treasure has<br>a tale to tell.</h2><p>Welcome visitors, share your discoveries, and make this little corner of the realm shine.</p><button class="primary-btn" data-view="gallery">Visit your gallery &nbsp; ↗</button></div><div class="gallery-visual">${d.slice(0,3).map((a,i)=>`<div class="arch-frame">${a.icon}</div>`).join('')}${d.length<2?'<div class="arch-frame">✦</div>':''}</div></section><div class="panel"><div class="panel-head"><h3>A visitor’s note</h3><span style="color:#c39b60">✧</span></div><div class="visitor-quote">${guests[state.guest%guests.length].line}</div><div style="display:flex;align-items:center;gap:9px;margin-top:18px"><span style="font-size:23px">${guests[state.guest%guests.length].icon}</span><div><strong style="font-size:10px">${guests[state.guest%guests.length].name.split(',')[0]}</strong><div style="font-size:9px;color:#999;margin-top:3px">A guest at your gallery</div></div></div><div style="border-top:1px solid var(--line);margin-top:16px;padding-top:13px"><div class="eyebrow" style="font-size:8px">A LITTLE INSPIRATION</div><div style="font:13px 'Playfair Display',serif;margin-top:7px">“Collect stories, not just things.”</div></div></div></div><div class="stat-row">${stat('✦','gold','TREASURY',state.gold+' G')}${stat('▧','sage','ON DISPLAY',d.length,'of 5 gallery spaces')}${stat('♧','blue','VISITORS TODAY',Math.max(1,Math.floor(d.length*1.5)),'curious souls')}${stat('◈','rose','CURATOR RENOWN',state.renown,'points')}</div><div class="lower-grid"><section class="panel"><div class="panel-head"><h3>Currently on display</h3><button class="link-btn" data-view="gallery">Manage gallery ↗</button></div><div class="artifact-list">${latest}</div></section><section class="panel"><div class="panel-head"><h3>Recent happenings</h3><span style="font-size:10px;color:#aaa">YOUR JOURNAL</span></div><div class="activity-list">${activityHtml}</div></section></div><section class="panel section-gap"><div class="panel-head"><h3>Where to next?</h3><span style="font-size:10px;color:#aaa">QUICK VISIT</span></div><div class="quick-actions"><button class="quick-action" data-view="guild"><span>⚔</span>Browse the guild & market</button><button class="quick-action" data-view="estate"><span>⌂</span>Decorate your mansion</button></div></section>`}
function galleryView(){const d=getDisplayed();const not=d.length<5?state.owned.filter(id=>!state.exhibited.includes(id)).map(item).filter(Boolean):[];const pedestals=d.slice(0,5).map(a=>`<div class="display-pedestal"><span>${a.icon}</span></div>`).join('');return `${heading('A HOUSE OF LITTLE WONDERS','My Gallery','Arrange your treasures and make every visitor feel at home.',`<button class="primary-btn" data-action="advance">☀ &nbsp;Welcome visitors</button>`)}<div class="room-banner"><div class="room-caption">✧ &nbsp;The Larkspur Gallery</div><div class="room-displays">${pedestals||'<div style="align-self:center;color:#fff;background:#4b5c4d99;padding:10px;border-radius:8px">Your first exhibit awaits</div>'}</div></div><div class="collection-stats"><div class="mini-stat"><b>${d.length}/5</b> exhibition spaces</div><div class="mini-stat"><b>+${d.length*7} G</b> daily visitor donations</div><div class="mini-stat"><b>${state.furniture.filter(id=>furnitureItem(id)?.room==='gallery').length}</b> gallery furnishings</div></div><div class="lower-grid"><section class="panel"><div class="panel-head"><h3>On display</h3><span style="font-size:10px;color:#9b9b93">${d.length} treasured ${d.length===1?'piece':'pieces'}</span></div><div class="artifact-list">${d.length?d.map(a=>`<div class="artifact-row"><div class="artifact-art">${a.icon}</div><div class="artifact-copy"><strong>${a.name}</strong><span>${a.kind} · ${a.rarity}</span></div><button class="quiet-btn" data-action="store" data-id="${a.id}">Store</button></div>`).join(''):'<div class="empty-note">Your display cases are waiting for their first treasures.</div>'}</div></section><section class="panel"><div class="panel-head"><h3>Ready to exhibit</h3><button class="link-btn" data-view="guild">Find treasures ↗</button></div><div class="artifact-list">${not.length?not.map(a=>`<div class="artifact-row"><div class="artifact-art">${a.icon}</div><div class="artifact-copy"><strong>${a.name}</strong><span>${a.kind} · ${a.rarity}</span></div><button class="secondary-btn" data-action="exhibit" data-id="${a.id}" ${d.length>=5?'disabled':''}>Display</button></div>`).join(''):'<div class="empty-note">No other treasures in storage. Visit the market or commission an expedition.</div>'}</div></section></div>`}
function itemCard(a){const has=owned(a.id);return `<article class="item-card"><div class="item-art ${a.tone}">${a.icon}${has?'<span class="owned-tag">In collection</span>':''}</div><div class="item-card-body"><h3>${a.name}</h3><p>${a.desc}</p><div class="card-meta"><span>${a.kind} · ${a.rarity}</span><span class="card-price">✦ ${a.price} G</span></div><button class="primary-btn card-button" data-action="buy-artifact" data-id="${a.id}" ${has?'disabled':''}>${has?'Already yours':'Acquire from merchant'}</button></div></article>`}
function collectionView(){const all=state.owned.map(item).filter(Boolean),display=state.exhibited.length;return `${heading('CURATED WITH CARE','Your Collection','A growing catalogue of curious things and wonderful stories.',`<button class="primary-btn" data-view="guild">＋ &nbsp;Find a treasure</button>`)}<div class="collection-stats"><div class="mini-stat"><b>${all.length}</b> objects collected</div><div class="mini-stat"><b>${display}</b> on display</div><div class="mini-stat"><b>${new Set(all.map(a=>a.kind)).size}</b> kinds represented</div><div class="mini-stat"><b>${all.filter(a=>a.rarity==='Rare').length}</b> rare discoveries</div></div>${all.length?`<div class="card-grid">${all.map(a=>`<article class="item-card"><div class="item-art ${a.tone}">${a.icon}<span class="owned-tag">${state.exhibited.includes(a.id)?'On display':'In storage'}</span></div><div class="item-card-body"><h3>${a.name}</h3><p>${a.desc}</p><div class="card-meta"><span>${a.kind} · ${a.rarity}</span><span>✦ +${a.renown} renown</span></div><button class="${state.exhibited.includes(a.id)?'secondary-btn':'primary-btn'} card-button" data-action="${state.exhibited.includes(a.id)?'store':'exhibit'}" data-id="${a.id}">${state.exhibited.includes(a.id)?'Return to storage':'Place on display'}</button></div></article>`).join('')}</div>`:`<div class="empty-card"><strong>A collection begins with one little thing.</strong>Visit the merchant or send an adventurer to find your first treasure.<br><br><button class="primary-btn" data-view="guild">Visit Guild & Market</button></div>`}`}

