function collectionView(){const all=state.owned.map(item).filter(Boolean),display=state.exhibited.length;return `${heading('CURATED WITH CARE','Your Collection','A growing catalogue of curious things and wonderful stories.',`<button class="primary-btn" data-view="guild">＋ &nbsp;Find a treasure</button>`)}<div class="collection-stats"><div class="mini-stat"><b>${all.length}</b> objects collected</div><div class="mini-stat"><b>${display}</b> on display</div><div class="mini-stat"><b>${new Set(all.map(a=>a.kind)).size}</b> kinds represented</div><div class="mini-stat"><b>${all.filter(a=>a.rarity==='Rare').length}</b> rare discoveries</div></div>${all.length?`<div class="card-grid">${all.map(a=>`<article class="item-card"><div class="item-art ${a.tone}">${a.icon}<span class="owned-tag">${state.exhibited.includes(a.id)?'On display':'In storage'}</span></div><div class="item-card-body"><h3>${a.name}</h3><p>${a.desc}</p><div class="card-meta"><span>${a.kind} · ${a.rarity}</span><span>✦ +${a.renown} renown</span></div><button class="${state.exhibited.includes(a.id)?'secondary-btn':'primary-btn'} card-button" data-action="${state.exhibited.includes(a.id)?'store':'exhibit'}" data-id="${a.id}">${state.exhibited.includes(a.id)?'Return to storage':'Place on display'}</button></div></article>`).join('')}</div>`:`<div class="empty-card"><strong>A collection begins with one little thing.</strong>Visit the merchant or send an adventurer to find your first treasure.<br><br><button class="primary-btn" data-view="guild">Visit Guild & Market</button></div>`}`}
function missionCard(m){const adv=adventurers.find(a=>a.id===m.adventurer);if(!adv)return '';return `<div class="commission-card"><div class="commission-top"><div class="adventurer-avatar">${adv.icon}</div><div class="commission-copy"><strong>${adv.name}</strong><span>${adv.role} · ${m.status==='active'?'On expedition':'Returned safely'}</span></div><span class="rarity">${m.status==='active'?`${m.daysLeft} day${m.daysLeft===1?'':'s'} left`:'Complete'}</span></div><p>${m.status==='active'?`Searching the old ruins for a special find. Expected discovery: ${adv.loot}.`:`Found a treasure and returned with a story to tell!`}</p><div class="commission-foot"><span class="commission-reward">${m.status==='active'?'◇ Commissioned expedition':'✦ Loot is ready in your collection'}</span>${m.status==='done'?`<button class="primary-btn" data-action="claim" data-id="${m.id}">Welcome home</button>`:''}</div>${m.status==='active'?`<div class="commission-progress"><span style="width:${Math.max(14,100-(m.daysLeft/adv.days*100))}%"></span></div>`:''}</div>`}
function guildView(){const missions=state.missions;return `${heading('THE OLD TOWN SQUARE','Guild & Market','Make a new friend, commission a brave soul, or bring home a curiosity.',`<div class="wallet" style="background:#fffefa;border:1px solid var(--line);border-radius:8px;padding:10px 12px">✦ &nbsp;<b>${state.gold} G</b></div>`)}<div class="tabs"><button class="tab-btn active" data-view="guild">✧ &nbsp;Merchant’s stall</button><button class="tab-btn" data-action="scroll" data-target="expeditions">⚔ &nbsp;Adventurers’ guild (${missions.filter(m=>m.status==='active').length} active)</button></div><div class="panel-head"><h3>Curiosities from near and far</h3><span style="font-size:10px;color:#999">A merchant has brought fresh wares</span></div><div class="card-grid">${artifacts.map(itemCard).join('')}</div><section class="panel section-gap" id="expeditions"><div class="panel-head"><div><h3>Adventurers’ Guild</h3><div style="font-size:10px;color:#999;margin-top:4px">Commission a companion to retrieve a rare find.</div></div><span class="rarity">${missions.filter(m=>m.status==='active').length} active</span></div>${missions.length?`<div class="guild-layout" style="grid-template-columns:1fr">${missions.map(missionCard).join('')}</div>`:''}<div class="guild-layout">${adventurers.map(a=>{const busy=missions.some(m=>m.adventurer===a.id&&m.status==='active');return `<div class="commission-card"><div class="commission-top"><div class="adventurer-avatar">${a.icon}</div><div class="commission-copy"><strong>${a.name}</strong><span>${a.role} · ${a.days} day expedition</span></div><span class="card-price">✦ ${a.cost} G</span></div><p>“${a.quote}”<br>Will search for <b>${a.loot}</b>.</p><div class="commission-foot"><span class="commission-reward">Reward: ${a.loot}</span><button class="primary-btn" data-action="commission" data-id="${a.id}" ${busy?'disabled':''}>${busy?'On an expedition':'Commission'}</button></div></div>`}).join('')}</div></section>`}
function estateView(){const ownedF=state.furniture.map(furnitureItem).filter(Boolean),placed=ownedF.filter(f=>f.room==='mansion');const icons=placed.map(f=>`<span title="${f.name}">${f.icon}</span>`).join('');return `${heading('A PLACE TO CALL YOUR OWN','My Mansion','A soft landing after a long day of collecting.',`<button class="secondary-btn" data-action="reset">↻ &nbsp;New story</button>`)}<div class="estate-layout"><section><div class="estate-room"><div class="room-caption">✧ &nbsp;The Sunroom</div><div class="room-floor-rug"></div><div class="furniture-in-room">${icons||'<span>🪴</span><span>🪑</span>'}</div></div><div class="collection-stats" style="margin-top:12px"><div class="mini-stat"><b>${placed.length}</b> furnishings in your sunroom</div><div class="mini-stat"><b>${state.furniture.filter(id=>furnitureItem(id)?.room==='gallery').length}</b> pieces in the gallery</div><div class="mini-stat"><b>+${placed.length*2} G</b> daily household income</div></div><section class="panel section-gap"><div class="panel-head"><h3>At home</h3><span style="font-size:10px;color:#aaa">A SMALL CORNER OF PEACE</span></div><div class="visitor-quote">A cup of tea, a good book, and the quiet company of your favorite things. The finest treasures are the moments in between.</div></section></section><section class="panel"><div class="panel-head"><div><h3>Estate furnishing shop</h3><div style="font-size:10px;color:#999;margin-top:4px">Make each room feel a little more like you.</div></div></div><div class="artifact-list">${furniture.map(f=>{const has=state.furniture.includes(f.id);return `<div class="artifact-row"><div class="artifact-art">${f.icon}</div><div class="artifact-copy"><strong>${f.name}</strong><span>${f.room==='gallery'?'Gallery':'Mansion'} · ${f.desc}</span></div><button class="${has?'quiet-btn':'secondary-btn'}" data-action="buy-furniture" data-id="${f.id}" ${has?'disabled':''}>${has?'Owned':`✦ ${f.price} G`}</button></div>`}).join('')}</div></section></div>`}
function render(){const views={home:homeView,gallery:galleryView,collection:collectionView,guild:guildView,estate:estateView};el('#view-container').innerHTML=views[activeView]();updateChrome()}
function buyArtifact(id){const a=item(id);if(!a||owned(id))return toast('That curiosity is already in your collection.');if(state.gold<a.price)return toast('Not quite enough gold. Welcome a few visitors or wait for an expedition.',true);state.gold-=a.price;state.owned.push(id);state.renown+=a.renown;activity(a.icon,`Acquired the ${a.name}`,`Added to your growing collection · +${a.renown} renown`);save();render();toast(`<b>${a.name}</b> is yours. What a lovely find!`)}
function exhibit(id){const a=item(id);if(!a||!owned(id)||state.exhibited.includes(id))return;if(state.exhibited.length>=5)return toast('All five display spaces are full. Store an exhibit first.',true);state.exhibited.push(id);state.renown+=3;activity(a.icon,`Put ${a.name} on display`,'Visitors will admire it in your gallery.');save();render();toast(`<b>${a.name}</b> now has a place of honor.`)}
function store(id){state.exhibited=state.exhibited.filter(x=>x!==id);const a=item(id);activity('📦',`Stored ${a?.name||'an exhibit'}`,'Your treasure is safe in the collection.');save();render();toast('Your display has been thoughtfully rearranged.')}
function commission(id){const a=adventurers.find(x=>x.id===id);if(!a)return;if(state.gold<a.cost)return toast('You need a little more gold for this commission.',true);if(state.missions.some(m=>m.adventurer===id&&m.status==='active'))return toast('They are already away on an expedition.',true);state.gold-=a.cost;const mission={id:'m'+Date.now(),adventurer:id,daysLeft:a.days,status:'active'};state.missions.push(mission);activity(a.icon,`${a.name} set out`,`${a.days} day expedition · ${a.loot}`);save();render();toast(`<b>${a.name}</b> is off on an adventure. Send them your best wishes!`)}
function claimMission(id){const m=state.missions.find(x=>x.id===id);if(!m||m.status!=='done')return;const adv=adventurers.find(a=>a.id===m.adventurer);let prize=artifacts.find(a=>a.name===adv.loot);if(owned(prize.id)){prize=artifacts.find(a=>!owned(a.id))||prize;}if(!owned(prize.id)){state.owned.push(prize.id);state.renown+=prize.renown;activity(prize.icon,`${adv.name} returned with ${prize.name}`,`A wonderful addition to your collection · +${prize.renown} renown`)}else{state.gold+=35;activity('✦',`${adv.name} found a generous buyer`, 'Your collection was complete, so they brought home 35 G instead.')}state.missions=state.missions.filter(x=>x.id!==id);save();render();toast(`<b>${adv.name}</b> has returned. A story and treasure await!`)}
function buyFurniture(id){const f=furnitureItem(id);if(!f||state.furniture.includes(id))return;if(state.gold<f.price)return toast('Save a little more gold for this lovely piece.',true);state.gold-=f.price;state.furniture.push(id);activity(f.icon,`Added ${f.name}`,`Your ${f.room==='gallery'?'gallery':'mansion'} feels more like home.`);save();render();toast(`<b>${f.name}</b> has found its new home.`)}
function nextDay(){const income=10+state.exhibited.length*7+state.furniture.filter(id=>furnitureItem(id)?.room==='mansion').length*2;state.gold+=income;state.day++;state.guest=(state.guest+1)%guests.length;let returned=[];state.missions.forEach(m=>{if(m.status==='active'){m.daysLeft--;if(m.daysLeft<=0){m.status='done';returned.push(adventurers.find(a=>a.id===m.adventurer)?.name)}}});activity('☀',`Day ${state.day} in Larkspur`,`Your gallery welcomed visitors and earned ${income} G.`);save();render();toast(`A new day dawns. Visitors left <b>${income} G</b> in your donation box.`);if(returned.length)setTimeout(()=>toast(`<b>${returned.join(' & ')}</b> returned from the expedition. Visit the guild to welcome them!`),450)}
function resetGame(){state={...initial,owned:[...initial.owned],exhibited:[...initial.exhibited],furniture:[],missions:[],activities:[]};activeView='home';localStorage.removeItem('larkspur-save');closeModal();visit('home');toast('A fresh story begins at Larkspur.')}
function showProfile(){el('#modal-card').innerHTML=`<button class="modal-close" data-action="close-modal">×</button><div class="eyebrow">THE LORD OF LARKSPUR</div><h2>Lord Aurelius</h2><p>A nobleman with a curious heart and an eye for the stories hidden in forgotten objects. Your collection, gold, and furnishings are saved in this browser.</p><div class="modal-options"><button class="modal-option" data-view="collection"><span class="option-icon">◇</span><span><strong>View your collection</strong><small>${state.owned.length} treasures gathered so far</small></span></button><button class="modal-option" data-action="close-modal"><span class="option-icon">✧</span><span><strong>Continue your day</strong><small>There is always another story to find.</small></span></button></div>`;el('#modal-backdrop').hidden=false}
function closeModal(){el('#modal-backdrop').hidden=true}

