function closeModal(){el('#modal-backdrop').hidden=true}
document.addEventListener('click',e=>{
  const viewButton=e.target.closest('[data-view]');
  if(viewButton){closeModal();visit(viewButton.dataset.view);return}
  const button=e.target.closest('[data-action]');if(!button)return;
  const id=button.dataset.id;
  switch(button.dataset.action){
    case 'advance':nextDay();break;
    case 'buy-artifact':buyArtifact(id);break;
    case 'exhibit':exhibit(id);break;
    case 'store':store(id);break;
    case 'commission':commission(id);break;
    case 'claim':claimMission(id);break;
    case 'buy-furniture':buyFurniture(id);break;
    case 'scroll':document.getElementById(button.dataset.target)?.scrollIntoView({behavior:'smooth',block:'start'});break;
    case 'reset':if(confirm('Start a new story? Your current collection and progress will be cleared.'))resetGame();break;
    case 'close-modal':closeModal();break;
  }
});
el('#mobile-menu').addEventListener('click',()=>el('#sidebar').classList.toggle('open'));
el('.avatar-button').addEventListener('click',showProfile);
el('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();el('#sidebar').classList.remove('open')}});
updateChrome();render();

