async (page) => {
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.locator('[data-view="guild"]').first().click();
  await page.locator('[data-action="buy-artifact"][data-id="feather"]').click();
  if (!(await page.getByText('Azure Griffin Feather').count())) throw new Error('market purchase failed');
  await page.locator('[data-view="gallery"]').first().click();
  await page.locator('[data-action="exhibit"][data-id="feather"]').click();
  await page.locator('[data-view="guild"]').first().click();
  await page.locator('[data-action="commission"][data-id="lina"]').click();
  await page.locator('[data-action="advance"]').click();
  await page.locator('[data-action="advance"]').click();
  await page.locator('[data-view="guild"]').first().click();
  await page.locator('[data-action="claim"]').click();
  await page.locator('[data-view="estate"]').first().click();
  await page.locator('[data-action="buy-furniture"][data-id="fern"]').click();
  await page.locator('[data-view="home"]').first().click();
  const result = await page.evaluate(() => JSON.parse(localStorage.getItem('larkspur-save')));
  console.log(JSON.stringify({gold:result.gold,day:result.day,owned:result.owned,exhibited:result.exhibited,furniture:result.furniture,missions:result.missions.length}));
}

